<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use function Sendzad\{email_catalog,brand_defaults,validate_brand,https_brand_url,brand_header_html,brand_footer_html,example_destination,merge_values,clean_html,clean_style,safe_url,email_dom,dom_body_html,compose_email,campaign_preflight,email_plaintext};

$catalog=email_catalog();
check('catalog contains sixteen unique original designs',static function()use($catalog){eq(count($catalog['templates']),16);eq(count(array_unique(array_column($catalog['templates'],'id'))),16);});
check('catalog contains ten reusable blocks',static fn()=>eq(count($catalog['blocks']),10));
check('collections contain ten business and six commerce designs',static function()use($catalog){eq(count(array_filter($catalog['templates'],static fn($t)=>$t['collection']==='Business')),10);eq(count(array_filter($catalog['templates'],static fn($t)=>$t['collection']==='Commerce')),6);});
check('responsive styles and allowlist are local trusted catalog values',static function()use($catalog){truth(str_contains($catalog['css'],'max-width:640px'));truth(in_array('tz-stack',$catalog['classes'],true));truth(!str_contains($catalog['css'],'url('));});
foreach($catalog['templates'] as $t)check('complete design metadata: '.$t['id'],static function()use($t){foreach(['id','name','subject','preheader','category','collection','description','html','edit_before_send'] as $key)truth(!empty($t[$key]));eq(substr_count($t['html'],'data-tz-header="standard"'),1);eq(substr_count($t['html'],'data-tz-footer="standard"'),1);eq(substr_count($t['html'],'data-tz-content="main"'),1);truth(strlen($t['html'])<95000);truth(!preg_match('/<(script|iframe|object|form)\b/i',$t['html']));});
foreach(['https://sendzad.com','https://sendzad.com/path?a=one&b=two'] as $u)check('HTTPS brand URL accepted: '.$u,static fn()=>truth(https_brand_url($u)));
foreach(['http://sendzad.com','javascript:alert(1)','https://user:pass@sendzad.com','//sendzad.com','https:bad','https://sendzad.com/a b',"https://sendzad.com/\nsecret"] as $u)check('unsafe brand URL rejected: '.json_encode($u),static function()use($u){eq(https_brand_url($u),false);rejects(static fn()=>validate_brand(['website'=>$u]));});
check('saved brand only contains documented fields',static function(){eq(count(validate_brand(['admin'=>'true','unknown'=>'x'])),count(brand_defaults()));truth(!array_key_exists('admin',validate_brand(['admin'=>'true'])));});
check('brand values reject merge-token recursion',static fn()=>rejects(static fn()=>validate_brand(['name'=>'{{email}}'])));
check('brand rejects oversized text and header injection',static function(){rejects(static fn()=>validate_brand(['name'=>str_repeat('A',121)]));rejects(static fn()=>validate_brand(['support_email'=>"a@sendzad.com\nBcc:x"]));});
check('multiline business address retained',static fn()=>eq(validate_brand(['postal_address'=>"12 Road\nLagos"])['postal_address'],"12 Road\nLagos"));
check('bad support address rejected',static fn()=>rejects(static fn()=>validate_brand(['support_email'=>'not-an-email'])));
check('footer escapes every plain brand value',static function(){$h=brand_footer_html(['name'=>'<script>x</script>','postal_address'=>"A & B\nLagos"],'https://sendzad.com/unsubscribe?k=a&v=b',2026);truth(!str_contains($h,'<script>'));truth(str_contains($h,'&lt;script&gt;'));truth(str_contains($h,'A &amp; B'));truth(str_contains($h,'?k=a&amp;v=b'));truth(str_contains($h,'<br'));});
check('empty optional links are absent rather than fabricated',static function(){$h=brand_footer_html(['name'=>'Brand','postal_address'=>'Address'],'https://sendzad.com/unsubscribe',2026);eq(substr_count($h,'<a '),1);truth(!str_contains($h,'Facebook'));truth(!str_contains($h,'Email preferences'));});
check('footer includes configured contact, social and legal links',static function(){$h=brand_footer_html(['name'=>'Brand','postal_address'=>'Address','support_email'=>'support@sendzad.com','phone'=>'+234 000','facebook_url'=>'https://facebook.com/brand','instagram_url'=>'https://instagram.com/brand','linkedin_url'=>'https://linkedin.com/company/brand','privacy_url'=>'https://sendzad.com/privacy','preferences_url'=>'https://sendzad.com/preferences'],'https://sendzad.com/unsubscribe',2026);eq(substr_count($h,'<a '),7);eq(substr_count($h,'clicktracking="off"'),7);truth(str_contains($h,'+234 000'));});
check('logo and website are safely rendered in header',static function(){$h=brand_header_html(['name'=>'Brand & Co','website'=>'https://sendzad.com','logo_url'=>'https://sendzad.com/logo.png']);truth(str_contains($h,'alt="Brand &amp; Co"'));truth(str_contains($h,'width="144"'));truth(str_contains($h,'href="https://sendzad.com"'));});
foreach(['https://example.com/x','https://sub.example.net','https://brand.invalid','https://mail.example','https://site.test'] as $u)check('example destination detected '.$u,static fn()=>truth(example_destination($u)));
check('real domains not misclassified as examples',static function(){eq(example_destination('https://sendzad.com'),false);eq(example_destination('https://notexample.com'),false);});
check('missing URL authorities and empty mail links are rejected',static function(){eq(safe_url('https:missing-host'),false);eq(safe_url('mailto:'),false);eq(safe_url('tel:'),false);});
check('email-safe Outlook styling is retained without accepting arbitrary CSS',static function(){eq(clean_style('mso-hide:all;mso-line-height-rule:exactly;mso-padding-alt:12px;overflow-wrap:anywhere;background-image:url(x)'),'mso-hide:all;mso-line-height-rule:exactly;mso-padding-alt:12px;overflow-wrap:anywhere');});
check('merge values do not invent recipient names',static function(){$v=merge_values(brand_defaults(),['email'=>'qa@sendzad.com','name'=>''],['preheader'=>'Hello'],'https://sendzad.com/unsubscribe',2026);eq($v['{{first_name}}'],'there');eq($v['{{year}}'],'2026');});

$brand=validate_brand(['name'=>'Example Studio','website'=>'https://sendzad.com','postal_address'=>"Test studio\nLagos",'support_email'=>'support@sendzad.com','preferences_url'=>'https://sendzad.com/preferences']);
$recipient=['id'=>str_repeat('a',32),'email'=>'test@sendzad.com','name'=>'Ada Reader'];
$unsub='https://sendzad.com/unsubscribe?k=synthetic-token';
$domCases=[];
$domCases['sanitizer retains responsive and managed module markers']=static function()use($catalog){$h=clean_html($catalog['templates'][0]['html']);truth(str_contains($h,'class="tz-stack tz-column"'));truth(str_contains($h,'data-tz-header="standard"'));truth(str_contains($h,'data-tz-footer="standard"'));truth(!str_contains($h,'<style'));};
$domCases['sanitizer removes attacker classes, scripts and invalid marker values']=static function(){$h=clean_html('<script>bad()</script><p class="evil tz-title" data-tz-footer="fake" onclick="bad()">Hi</p><span data-tz-header="standard">X</span>');truth(!str_contains($h,'script'));truth(!str_contains($h,'evil'));truth(!str_contains($h,'onclick'));truth(!str_contains($h,'data-tz-'));truth(str_contains($h,'tz-title'));};
$domCases['compose renders exactly one footer and one preheader']=static function()use($catalog,$brand,$recipient,$unsub){$t=$catalog['templates'][0];$mail=compose_email($t,$recipient,$brand,$unsub,null,2026);$d=email_dom($mail['html']);$xp=new DOMXPath($d);eq($xp->query('//*[@data-tz-footer]')->length,1);eq($xp->query('//*[@data-tz-preheader]')->length,1);truth(str_contains($mail['html'],'Hi Ada'));truth(str_contains($mail['html'],'max-width:640px'));truth(str_contains($mail['html'],'<!--[if mso]>'));truth(!preg_match('/\{\{[^}]+\}\}/',$mail['html']));};
$domCases['duplicate standard modules are deduplicated before sending']=static function()use($catalog,$brand,$recipient,$unsub){$t=$catalog['templates'][0];$t['html']=clean_html($t['html']).$catalog['footer'].$catalog['header'];$mail=compose_email($t,$recipient,$brand,$unsub);eq(substr_count($mail['html'],'data-tz-footer="standard"'),1);eq(substr_count($mail['html'],'data-tz-header="standard"'),1);};
$domCases['custom HTML receives a fallback brand footer']=static function()use($brand,$recipient,$unsub){$mail=compose_email(['subject'=>'Hi','html'=>'<p>Custom content</p>','text_body'=>'Custom content'],$recipient,$brand,$unsub);eq(substr_count($mail['html'],'data-tz-footer="standard"'),1);truth(str_contains($mail['html'],'Custom content'));};
$domCases['unsubscribe and preference links bypass click tracking']=static function()use($catalog,$brand,$recipient,$unsub){$seen=[];$track=static function($url)use(&$seen){$seen[]=$url;return 'https://sendzad.com/track?k=synthetic';};$m=compose_email($catalog['templates'][0],$recipient,$brand,$unsub,$track);truth(count($seen)>0);truth(!in_array($unsub,$seen,true));truth(!in_array($brand['preferences_url'],$seen,true));truth(str_contains($m['html'],'href="'.$unsub.'"'));};
$domCases['recipient HTML is escaped during interpolation']=static function()use($brand,$recipient,$unsub){$recipient['name']='<img src=x onerror=bad()>';$m=compose_email(['subject'=>'Hi','html'=>'<p>{{name}}</p>'],$recipient,$brand,$unsub);truth(str_contains($m['html'],'&lt;img'));truth(!str_contains($m['html'],'<img src="x"'));};
$domCases['plain text omits managed modules and adds exactly one unsubscribe line']=static function()use($catalog,$brand,$recipient,$unsub){$t=$catalog['templates'][0];$plain=email_plaintext($t['html']);truth(!str_contains($plain,'Unsubscribe'));$m=compose_email($t,$recipient,$brand,$unsub,null,2026);eq(substr_count($m['text'],'Unsubscribe:'),1);truth(str_contains($m['text'],'Hi Ada'));};
$domCases['preflight blocks catalog placeholders and example links']=static function()use($catalog,$brand){$t=array_values(array_filter($catalog['templates'],static fn($t)=>$t['id']==='catalog'))[0];$r=campaign_preflight($t,$brand);eq($r['ready'],false);truth(count($r['errors'])>=2);truth(in_array('Review stock photographs to ensure they match your products and message.',$r['warnings'],true));};
$domCases['preflight accepts completed welcome with genuine branding']=static fn()=>eq(campaign_preflight($catalog['templates'][0],$brand)['ready'],true);
$domCases['preflight rejects missing website and address']=static function()use($catalog){$r=campaign_preflight($catalog['templates'][0],brand_defaults());eq($r['ready'],false);truth(count($r['errors'])>=2);};
$domCases['preflight rejects unsupported merge fields and bad URLs']=static function()use($brand){$r=campaign_preflight(['subject'=>'{{secret}}','html'=>'<a href="javascript:bad()">Open</a>'],$brand);eq($r['ready'],false);truth(count($r['errors'])>=2);};
$domCases['preheader personalization matches subject and preview']=static function()use($catalog,$brand,$recipient,$unsub){$t=$catalog['templates'][0];$t['preheader']='An update from {{brand_name}} for {{first_name}}';$m=compose_email($t,$recipient,$brand,$unsub);truth(str_contains($m['html'],'An update from Example Studio for Ada'));eq($m['subject'],'Welcome to Example Studio');};
foreach($domCases as $name=>$run){if(class_exists('DOMDocument'))check($name,$run);else{$skips++;echo "SKIP $name (PHP DOM is unavailable)\n";}}
result();
